import assert from "node:assert/strict";
import { execFileSync, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { readFile, writeFile, access } from "node:fs/promises";
import { join } from "node:path";
const root = "D:/Packages/PI-Desktop/worktrees/owner-local-control", scratch = process.env.PI_SCRATCH_DIR;
const expected = "3a65c0b957e38dad06ade7dae78f79d958fb659f", base = "fd28eb89866ac513912ed109716e7120cf60f18c";
const git = (...args) => execFileSync("git", args, { cwd: root, encoding: "utf8" }).trim();
const hash = bytes => createHash("sha256").update(bytes).digest("hex");
const output = join(scratch, "handoff-surfaces-candidate.json");
await assert.rejects(access(output)); assert.equal(git("status", "--porcelain"), ""); assert.equal(git("rev-parse", "HEAD"), expected);
assert.equal(git("rev-parse", "origin/main"), base); git("merge-base", "--is-ancestor", base, expected);
const paths = [...new Set([...git("diff-tree", "--no-commit-id", "--name-only", "-r", expected).split("\n"),
  "apps/desktop/electron/main/plugin-panel-senders.ts", "apps/desktop/electron/main/external-resource-activity.ts",
  "apps/desktop/electron/main/runtime/handoff-admission.ts", "apps/desktop/electron/main/plugin-lifecycle.ts",
  "apps/desktop/test/helpers/plugin-surface-electron-hook.mjs", "apps/desktop/test/helpers/current-source-import-hooks.mjs",
  "apps/desktop/test/helpers/current-source-vite.mjs", "apps/desktop/test/helpers/owner-runtime-import-hooks.mjs",
  "apps/desktop/test/helpers/ts-import-hooks.mjs", "scripts/e2e/sidecar-handoff-build.mjs"] )].sort();
const inputs = []; for (const path of paths) { const bytes = await readFile(join(root, path)); inputs.push({ path, bytes: bytes.length, sha256: hash(bytes) }); }
const env = { ...process.env, TEMP: scratch, TMP: scratch,
  PI_COMMAND_CENTER_DEPENDENCIES: "C:/Users/Administrator/.pi-desktop/scratch/a6fa9016-c24e-432f-8859-b0744dea889d/p0-dependencies" };
async function run(name, args) {
  const child = spawn(process.execPath, args, { cwd: root, env, stdio: ["ignore", "pipe", "pipe"] }); let text = "";
  for (const stream of [child.stdout, child.stderr]) stream.on("data", bytes => { text += bytes; });
  const code = await new Promise((resolve, reject) => { child.once("error", reject); child.once("close", resolve); });
  const path = join(scratch, name); await writeFile(path, text); assert.equal(code, 0, text.slice(-6000));
  return { path, text, bytes: Buffer.byteLength(text), sha256: hash(text) };
}
const regression = await run("handoff-surfaces-candidate-regressions.log", ["--test", "--test-timeout=25000", "apps/desktop/test/handoff-plugin-surfaces.test.mjs"]);
assert.match(regression.text, /tests 23/); assert.match(regression.text, /pass 23/);
for (const key of ["fail", "cancelled", "skipped"]) assert.match(regression.text, new RegExp(key + " 0"));
const native = await run("handoff-surfaces-candidate-native.log", ["scripts/e2e-plugin-surfaces-handoff.mjs"]);
const report = JSON.parse(native.text); assert.equal(report.candidate, expected); assert.equal(report.base, base);
assert.equal(report.status, "PASS_WITH_UNQUALIFIED_NATIVE_RESOURCES"); assert.equal(report.dirty, false); assert.equal(report.endedDirty, false);
assert.equal(report.sourceInputsUnchanged, true); assert.equal(report.originalProcessExitObserved, true);
assert.equal(report.originalPluginExitsObserved, true); assert.equal(report.originalWebContentsDestroyed, 2);
assert.equal(report.qualifiedNativeFamilyClosure, false); assert.equal(report.activity.operations, 0); assert.equal(report.activity.uncontainedResources, 6);
assert.equal(report.passed.length, 4); assert.equal(git("status", "--porcelain"), ""); assert.equal(git("rev-parse", "HEAD"), expected);
for (const input of inputs) assert.equal(hash(await readFile(join(root, input.path))), input.sha256, input.path);
const result = { candidate: expected, base, status: report.status, cleanBefore: true, cleanAfter: true, focusedInputsUnchanged: true,
  focusedInputs: inputs, focusedInputsSha256: hash(JSON.stringify(inputs)), regression: { passed: 23, log: regression.path, bytes: regression.bytes, sha256: regression.sha256 },
  native: report, limitations: ["Focused changed/direct inputs are not a full dependency manifest. Native bundle inputs are separately retained.",
    "Node plugin exit and Electron page/root exit are not complete native-family closure proof.", "Shortcut registration edge is deterministic; no OS key injection.",
    "Full H1 inventory, source status transport, fenced Desktop composition and H2-H5 remain unfinished."] };
await writeFile(output, JSON.stringify(result, null, 2) + "\n"); console.log(JSON.stringify({ output, candidate: expected, status: result.status, regressionPassed: 23, nativeChecks: 4, focusedInputs: inputs.length, nativeDirectory: report.directory }));

